const body = $input.first().json.body || $input.first().json;
const action = body.action;

let sql;
if (action === 'connect') {
  const creds = JSON.stringify(body.credentials || {}).replace(/'/g, "''");
  sql = `INSERT INTO integrations (user_email, platform, store_url, credentials, status) VALUES ('${body.userEmail}', '${body.platform}', '${body.storeUrl}', '${creds}'::jsonb, 'connected') ON CONFLICT (user_email, store_url) DO UPDATE SET credentials = EXCLUDED.credentials, status = 'connected', updated_at = NOW() RETURNING *;`;
} else if (action === 'disconnect') {
  sql = `UPDATE integrations SET status = 'disconnected', updated_at = NOW() WHERE id = ${body.id} RETURNING *;`;
} else if (action === 'list') {
  sql = `SELECT * FROM integrations WHERE user_email = '${body.userEmail}' ORDER BY created_at DESC;`;
} else {
  sql = `SELECT 'unknown action' as error;`;
}

return [{ json: { sql, action } }];
